#raw
"""Galaxy runner for MantidTotalScattering.

Galaxy hands us datasets, not run numbers, so this wrapper does the three
things that stand between a Galaxy history and a MantidTotalScattering
reduction:

  1. Stages each dataset under a name Mantid and MTS can work with. Galaxy
     dataset paths end in ``.dat`` and carry no run number; MTS keys its
     caches off the file basename, so every input gets a distinct, stable name.

  2. Synthesises a zero-signal sample background when the user has none. MTS
     always loads and subtracts a container; subtracting zero is the honest
     way to express "no container was measured" without forking the reduction.

  3. Builds the MTS input JSON, including the off-cluster settings that a
     containerised run needs (``DummyExpt`` so no ONCat/IPTS lookup is
     attempted, ``CacheDirMTS`` inside the job directory, and a facility
     config that does not live under /SNS).

The JSON it builds is written out as a tool output so a run can always be
reproduced with a plain ``mantidtotalscattering input.json``.
"""

import argparse
import json
import os
import shutil
import sys


# MTS reads these from the facility config on the analysis cluster. Off the
# cluster we write our own copy; these values match the defaults the reduction
# falls back to internally.
FACILITY_CONFIG_DEFAULTS = {
    "SNS": {
        "NOM": {
            "QParamsProcessing": "0.01,0.001,40.0",
            "TMIN": 300.0,
            "TMAX": 16667.0,
            "ResampleX": -6000,
            "ReGenerateGrouping": 0,
            "QMaxByBank": "35,25,40,40,40,20",
            "TMinBragg": "0.7,0.7,0.9,1.5,1.6,1.1",
            "TMaxBragg": "17,18.5,19,18.5,16.9,17",
            "TBinBragg": "-0.0008",
        },
        "PG3": {
            "QParamsProcessing": "0.01,0.001,40.0",
            "TMIN": 300.0,
            "TMAX": 16667.0,
            "ResampleX": -8000,
            "ReGenerateGrouping": 0,
            "TBinBragg": "-0.0008",
        },
    }
}

# Shipped inside the MantidTotalScattering image. Used when the history has no
# calibration or grouping dataset, so that a two-file run works out of the box.
IMAGE_DEFAULTS = {
    "NOM": {
        "calibration": "/app/examples/sns/nomad_cal.h5",
        "grouping": "/app/examples/sns/groupings/nomad_group_16_8_masked.xml",
    }
}

ROLES = (
    "sample_files",
    "normalization_files",
    "sample_background_files",
    "sample_background_background_files",
    "normalization_background_files",
)


def stage_inputs(params, staging_dir):
    """Give every input dataset a distinct, loadable filename.

    @param params: dict, the tool parameters
    @param staging_dir: str, directory to stage into

    @return: dict of role -> list of staged absolute paths
    """
    os.makedirs(staging_dir, exist_ok=True)
    staged = {}
    for role in ROLES:
        paths = []
        for index, entry in enumerate(params.get(role) or []):
            source = entry["path"]
            target = os.path.join(
                staging_dir, "{0}_{1}.nxs".format(role[:-6], index))
            if os.path.exists(target):
                os.remove(target)
            # A symlink keeps large NeXus files from being copied, and Mantid
            # follows it happily.
            os.symlink(os.path.abspath(source), target)
            paths.append(target)
        staged[role] = paths
    return staged


def make_zero_background(reference_file, output_file):
    """Write a background NeXus with the reference's geometry and no counts.

    MTS unconditionally loads and subtracts a container run. When no container
    was measured - the usual case for simulated data - subtracting a workspace
    that is zero everywhere leaves the sample untouched, which is exactly the
    intended meaning.

    @param reference_file: str, NeXus file whose instrument/geometry to copy
    @param output_file: str, where to write the zero-signal NeXus

    @return: str, output_file
    """
    from mantid.simpleapi import (
        CreateSingleValuedWorkspace, Load, Multiply, SaveNexusProcessed)

    reference = Load(Filename=reference_file, OutputWorkspace="zero_bkg_ref")
    zero = CreateSingleValuedWorkspace(0.0, OutputWorkspace="zero_scalar")
    background = Multiply(
        LHSWorkspace=reference, RHSWorkspace=zero, OutputWorkspace="zero_bkg")
    SaveNexusProcessed(InputWorkspace=background, Filename=output_file)
    return output_file


# The reduction rebins to this Q binning while focussing, before the final
# merge. Fine is good, but see processing_q_params for when it is not.
DEFAULT_PROCESSING_Q_STEP = 0.001
DEFAULT_PROCESSING_Q_MIN = 0.01


def absorption_enabled(params):
    """True when either section asks for an absorption correction."""
    for section in ("sample", "normalization"):
        if params[section].get("absorption_correction") not in (None, "", "None"):
            return True
    return False


def processing_q_params(params):
    """Q binning used while focussing, as a Rebin parameter string.

    Without an absorption correction the detectors are grouped before this
    rebin, so a fine step costs almost nothing. With an absorption correction
    the reduction has to rebin every pixel on its own so it can divide by a
    pixel-level absorption workspace, and a 0.001 step across 40 inverse
    angstroms over a 100k pixel instrument is tens of gigabytes. There we fall
    back to the output binning, which is what actually survives the job.

    @param params: dict, the tool parameters

    @return: str, e.g. "0.01,0.001,40.0"
    """
    merging = params["merging"]
    override = params["advanced"].get("processing_q_step")
    if override:
        step = override
    elif absorption_enabled(params):
        step = merging["q_delta"]
    else:
        step = DEFAULT_PROCESSING_Q_STEP

    q_min = merging["q_min"] or DEFAULT_PROCESSING_Q_MIN

    return "{0},{1},{2}".format(q_min, step, merging["q_max"])


def write_facility_config(config_dir, facility, instrument, q_params=None):
    """Write the facility config MTS expects to find on the analysis cluster.

    @param config_dir: str, directory to write into
    @param facility: str
    @param instrument: str
    @param q_params: str or None, overrides QParamsProcessing

    @return: str, path to the written auto_config.json
    """
    os.makedirs(config_dir, exist_ok=True)
    defaults = FACILITY_CONFIG_DEFAULTS.get(facility, {}).get(instrument)
    if defaults is None:
        defaults = {
            "QParamsProcessing": "0.01,0.001,40.0",
            "TMIN": 300.0,
            "TMAX": 16667.0,
            "ReGenerateGrouping": 0,
        }
    contents = dict(defaults)
    if q_params:
        contents["QParamsProcessing"] = q_params
    contents["CacheDir"] = os.path.abspath(
        os.path.join(config_dir, os.pardir, "cache"))
    os.makedirs(contents["CacheDir"], exist_ok=True)

    config_file = os.path.join(config_dir, "auto_config.json")
    with open(config_file, "w") as handle:
        json.dump(contents, handle, indent=4)

    # Older MantidTotalScattering reads this unconditionally for non-PG3
    # instruments. A header-only file means "no detector sub-grouping".
    with open(os.path.join(config_dir, "group_index.txt"), "w") as handle:
        handle.write("group start stop\n")

    return config_file


def _correction(name):
    """Turn a 'None' selection into an absent JSON section."""
    if not name or name == "None":
        return None
    return {"Type": name}


def _inelastic(settings):
    if not settings or settings.get("type") in (None, "", "None"):
        return None
    return {
        "Type": settings["type"],
        "Order": settings["order"],
        "Self": settings["self"],
        "Interference": settings["interference"],
        "FitSpectrumWith": settings["fit_spectrum_with"],
        "LambdaBinningForFit": settings["lambda_binning_for_fit"],
        "LambdaBinningForCalc": settings["lambda_binning_for_calc"],
    }


def _geometry(geometry):
    shape = geometry.get("shape", "Cylinder")
    if shape == "HollowCylinder":
        return {
            "Shape": "HollowCylinder",
            "InnerRadius": geometry["inner_radius"],
            "OuterRadius": geometry["outer_radius"],
            "Height": geometry["height"],
        }
    return {
        "Shape": "Cylinder",
        "Radius": geometry["radius"],
        "Height": geometry["height"],
    }


def build_mts_config(params, staged, calibration_file, grouping_file,
                     config_file, cache_dir, output_dir):
    """Assemble the MantidTotalScattering input JSON.

    @param params: dict, the tool parameters
    @param staged: dict of role -> list of staged file paths
    @param calibration_file: str, calibration HDF5 to use
    @param grouping_file: str or None, initial detector grouping
    @param config_file: str, facility config for this run
    @param cache_dir: str, writable cache directory
    @param output_dir: str, where the reduction writes its results

    @return: dict, ready to be dumped as the MTS input JSON
    """
    sample = params["sample"]
    normalization = params["normalization"]
    merging = params["merging"]
    focus = params["align_and_focus"]
    advanced = params["advanced"]

    sample_section = {
        "Filenames": staged["sample_files"],
        "Background": {"Filenames": staged["sample_background_files"]},
        "Material": sample["material"],
        "MassDensity": sample["mass_density"],
        "PackingFraction": sample["packing_fraction"],
        "Geometry": _geometry(sample["geometry"]),
    }
    if staged["sample_background_background_files"]:
        sample_section["Background"]["Background"] = {
            "Filenames": staged["sample_background_background_files"]}

    for key, value in (
        ("AbsorptionCorrection", _correction(sample["absorption_correction"])),
        ("MultipleScatteringCorrection",
         _correction(sample["multiple_scattering_correction"])),
        ("InelasticCorrection", _inelastic(sample.get("inelastic_correction"))),
    ):
        if value is not None:
            sample_section[key] = value

    normalization_section = {
        "Filenames": staged["normalization_files"],
        "Material": normalization["material"],
        "MassDensity": normalization["mass_density"],
        "PackingFraction": normalization["packing_fraction"],
        "Geometry": _geometry(normalization["geometry"]),
    }
    if staged["normalization_background_files"]:
        normalization_section["Background"] = {
            "Filenames": staged["normalization_background_files"]}
    for key, value in (
        ("AbsorptionCorrection",
         _correction(normalization["absorption_correction"])),
        ("MultipleScatteringCorrection",
         _correction(normalization["multiple_scattering_correction"])),
    ):
        if value is not None:
            normalization_section[key] = value

    align_and_focus = {"TMin": focus["tmin"], "TMax": focus["tmax"]}
    extra = (focus.get("extra_args") or "").strip()
    if extra:
        align_and_focus.update(json.loads(extra))

    merging_section = {
        "QBinning": [merging["q_min"], merging["q_delta"], merging["q_max"]],
    }
    if grouping_file:
        # 'Initial' focuses detectors during align-and-focus, which is what
        # keeps a 100k pixel instrument inside a sane memory budget. 'Output'
        # is deliberately left out so the final focussing uses the grouping
        # from the calibration file, whose bank count matches QMaxByBank.
        merging_section["Grouping"] = {"Initial": grouping_file}

    config = {
        "Facility": params["facility"],
        "Instrument": params["instrument"],
        "Title": params["title"],
        # No ONCat/IPTS lookup: these files are not on the analysis cluster.
        "DummyExpt": True,
        "AutoConfigFile": config_file,
        "Sample": sample_section,
        "Normalization": normalization_section,
        "Calibration": {"Filename": calibration_file},
        "AlignAndFocusArgs": align_and_focus,
        "HighQLinearFitRange": merging["high_q_linear_fit_range"],
        "Merging": merging_section,
        "CacheDirMTS": cache_dir,
        "OutputDir": output_dir,
    }

    levels = merging.get("self_scattering_levels") or []
    if levels:
        config["SelfScatteringLevelCorrection"] = {
            "Bank{0}".format(level["bank"]): [level["min"], level["max"]]
            for level in levels
        }

    if advanced.get("beam_height") is not None:
        config["BeamHeight"] = advanced["beam_height"]
    if advanced.get("push_positive_level") is not None:
        sample_section["PushPositiveLevel"] = advanced["push_positive_level"]
    if advanced.get("debug_mode"):
        config["DebugMode"] = True

    return config


def deep_update(base, overrides):
    """Merge ``overrides`` into ``base``, recursing into nested dicts.

    @param base: dict, modified in place
    @param overrides: dict

    @return: dict, base
    """
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            deep_update(base[key], value)
        else:
            base[key] = value
    return base


def quiet_mantid(home):
    """Stop Mantid phoning home from a compute node with no egress."""
    properties_dir = os.path.join(home, ".mantid")
    os.makedirs(properties_dir, exist_ok=True)
    with open(os.path.join(properties_dir, "Mantid.user.properties"),
              "a") as handle:
        handle.write("\nUpdateInstrumentDefinitions.OnStartup = 0\n")
        handle.write("CheckMantidVersion.OnStartup = 0\n")
        handle.write("usagereports.enabled = 0\n")


def collect_outputs(output_dir, title, destinations):
    """Copy the reduction's title-named results to fixed output paths.

    @param output_dir: str, the reduction's OutputDir
    @param title: str, the reduction Title, which names its output files
    @param destinations: dict of relative source path -> destination path

    @return: list of str, the destinations that were actually written
    """
    written = []
    for relative, destination in destinations.items():
        source = os.path.join(output_dir, relative.format(title=title))
        if os.path.isfile(source):
            shutil.copyfile(source, destination)
            written.append(destination)
    return written


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--params", required=True)
    parser.add_argument("--extra-file-lists", required=True)
    parser.add_argument("--work-dir", default=".")
    parser.add_argument("--config-out", required=True)
    parser.add_argument("--sofq-out", required=True)
    parser.add_argument("--gsas-out", required=True)
    args = parser.parse_args(argv)

    with open(args.params) as handle:
        params = json.load(handle)
    with open(args.extra_file_lists) as handle:
        params.update(json.load(handle))

    work_dir = os.path.abspath(args.work_dir)
    staging_dir = os.path.join(work_dir, "staged")
    output_dir = os.path.join(work_dir, "output")
    cache_dir = os.path.join(work_dir, "cache")
    config_dir = os.path.join(work_dir, "mts_config")
    for directory in (output_dir, cache_dir):
        os.makedirs(directory, exist_ok=True)

    quiet_mantid(os.environ.get("HOME", work_dir))

    if not params["sample_files"]:
        parser.error("At least one sample file is required.")
    if not params["normalization_files"]:
        parser.error("At least one normalization file is required.")

    inelastic = (params["sample"].get("inelastic_correction") or {})
    if inelastic.get("type") == "Placzek":
        parser.error(
            "Placzek inelastic correction reads beam monitors from the raw "
            "run on the analysis cluster, which is not available for "
            "file-based input. Choose 'None' for this tool.")

    staged = stage_inputs(params, staging_dir)

    if not staged["sample_background_files"]:
        print("[Info] No sample background supplied; using a zero-signal "
              "background so the container subtraction is a no-op.")
        staged["sample_background_files"] = [make_zero_background(
            staged["sample_files"][0],
            os.path.join(staging_dir, "sample_background_0.nxs"))]

    instrument = params["instrument"]
    defaults = IMAGE_DEFAULTS.get(instrument, {})
    calibration_file = params.get("calibration_file") or defaults.get(
        "calibration")
    if not calibration_file or not os.path.isfile(calibration_file):
        parser.error(
            "A calibration file is required and no default is available for "
            "instrument '{0}'.".format(instrument))
    grouping_file = params.get("grouping_file") or defaults.get("grouping")
    if grouping_file and not os.path.isfile(grouping_file):
        grouping_file = None

    config_file = write_facility_config(
        config_dir, params["facility"], instrument,
        q_params=processing_q_params(params))

    config = build_mts_config(
        params, staged, calibration_file, grouping_file, config_file,
        cache_dir, output_dir)

    overrides_file = params["advanced"].get("config_overrides")
    if overrides_file:
        with open(overrides_file) as handle:
            deep_update(config, json.load(handle))

    with open(args.config_out, "w") as handle:
        json.dump(config, handle, indent=4)
    print("[Info] MantidTotalScattering input written to {0}".format(
        args.config_out))

    # Point the reduction at our facility config even on images that predate
    # the 'AutoConfigFile' key.
    os.environ["MTS_CONFIG_DIR"] = config_dir
    import total_scattering.params as mts_params
    mts_params.config_loc = {
        params["facility"]: {instrument: config_file}
    }

    from total_scattering.cli import main as mts_main
    mts_main(config=config)

    written = collect_outputs(output_dir, config["Title"], {
        os.path.join("SofQ", "{title}.nxs"): args.sofq_out,
        os.path.join("GSAS", "{title}.gsa"): args.gsas_out,
    })
    if args.sofq_out not in written:
        print("[Error] The reduction produced no S(Q) file.", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
#end raw
